const reportUptimeSites = `-- name: ReportUptimeSites :many
SELECT l.environment, m.id, m.name, m.url, m.cert_days, m.cert_valid,
       coalesce(sum(d.checks_up), 0)::integer   AS up,
       coalesce(sum(d.checks_down), 0)::integer AS down,
       coalesce(sum(d.ping_sum), 0)::bigint     AS ping_sum,
       coalesce(sum(d.ping_count), 0)::integer  AS ping_count
FROM project_uptime_monitors l
JOIN uptime_monitors m ON m.id = l.monitor_id
LEFT JOIN uptime_daily d ON d.monitor_id = m.id AND d.day >= $1::date AND d.day <= $2::date
WHERE l.project_id = $3
GROUP BY l.environment, m.id
ORDER BY l.environment = 'prod' DESC, lower(m.name)
LIMIT 20
`

type ReportUptimeSitesParams struct {
	FromDay   time.Time `json:"from_day"`
	ToDay     time.Time `json:"to_day"`
	ProjectID uuid.UUID `json:"project_id"`
}

type ReportUptimeSitesRow struct {
	Environment string    `json:"environment"`
	ID          uuid.UUID `json:"id"`
	Name        string    `json:"name"`
	Url         string    `json:"url"`
	CertDays    *int32    `json:"cert_days"`
	CertValid   *bool     `json:"cert_valid"`
	Up          int32     `json:"up"`
	Down        int32     `json:"down"`
	PingSum     int64     `json:"ping_sum"`
	PingCount   int32     `json:"ping_count"`
}

// Les sites du projet et leur mois : disponibilite et temps de reponse,
// sommes des agregats journaliers du mois.
func (q *Queries) ReportUptimeSites(ctx context.Context, arg ReportUptimeSitesParams) ([]ReportUptimeSitesRow, error) {
	rows, err := q.db.Query(ctx, reportUptimeSites, arg.FromDay, arg.ToDay, arg.ProjectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReportUptimeSitesRow{}
	for rows.Next() {
		var i ReportUptimeSitesRow
		if err := rows.Scan(
			&i.Environment,
			&i.ID,
			&i.Name,
			&i.Url,
			&i.CertDays,
			&i.CertValid,
			&i.Up,
			&i.Down,
			&i.PingSum,
			&i.PingCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

